with unpacked as (select id, coupon_codes, ship_to, exists(items, x -> x.price > 100) as has_premium_item, coalesce(ship_to.zip, 'UNKNOWN') as zip_or_unknown, array_join(array_sort(coupon_codes), ',') as coupons_text, ship_to.city as ship_city from carts) select ship_city, count(distinct id) as distinct_ids, count(case when ship_city = 'Singapore' then 1 end) as singapore_count, sort_array(collect_set(ship_city)) as ship_city_list, count(*) filter (where ship_city = 'Tokyo') as tokyo_rows, count(distinct id) as distinct_ids_2 from unpacked group by 1 having count(distinct id) > 1 order by distinct_ids_2 desc
